INSERT INTO `phinxlog` (`version`, `migration_name`, `start_time`, `end_time`, `breakpoint`) VALUES
(20240108120652, 'Initial', '2024-01-08 12:06:52', '2024-01-08 12:06:52', 0);
INSERT INTO `project` (`id`, `name`, `slug`, `group_id`, `author_id`, `logo`, `reference`, `description`, `region`, `type`, `phase`, `start`, `end`, `status`, `created_at`, `site_address_one`, `site_address_two`, `site_address_city`, `site_address_postcode`, `employer_liabilty_insurance`, `public_product_insurance`, `pricing_doc_required`, `gia`, `archived`) VALUES
(16855, 'Kingsland Road, London', 'kingsland-road-london', 1246, NULL, '333 Kingsland Rd Image.JPG', '', '<p>The demolition of existing buildings and structures and erection of a part 2 and part 3 storey building to create a new primary school (Use Class D1) for up to 350 pupils; and erection of an 11 storey (plus basement) building comprising: 298sqm Use Class A1/A2/A3 floorspace (133sqm net lettable); and 68 residential units; refuse and recycling facilities; cycle parking; and landscaping.</p>', 4, 24, 1, '2017-12-04', '2019-03-01', 2, '2018-03-15 12:53:05', '', '\"\"', NULL, '', 7, 7, 0, '0', 1),
(17377, 'Purley Rise Purley', 'purley-rise-purley', 2142, NULL, 'Webfriendly6.jpg', 'Purley Rise', '<p class=\"\\\">Construciton of a new build block of eight flats all for private sale.&nbsp;</p>', 4, 23, 1, '2018-10-15', '2019-09-30', 2, '2018-11-23 13:55:33', '15 Purley Rise', '\"\"', NULL, 'CR8 3AW', 7, 7, 0, '0', 1),
(17421, 'Bellenden Road Peckham', 'bellenden-road-peckham', 2352, NULL, 'Bellenden 1.JPG', '43BR', '<p class=\"\\\">The construction of a new build development to provide 6nr 1,2, and 3-bedroom apartments and 3nr 4-bedroom townhouses.</p>', 4, 23, 1, '2018-10-01', '2019-09-30', 2, '2019-01-07 09:45:01', '43 Bellenden Road, Peckham, London', '\"\"', NULL, '', 7, 7, 0, '0', 1),
