(23617, 'Ummed Villa', 'ummed-villa', 20738, NULL, NULL, 'UV001', '<p>Demolition of existing house, alterations, erection of replacement single/two storey house incorporating dormer extensions with accommodation within the roof space, double garage and swimming pool</p>', 9, 23, 1, '2022-11-01', '2024-05-01', 1, '2022-11-08 06:45:30', 'Ummed Villa', 'Birch Lane', 'Purley', 'CR8 3LH', 2, 2, 0, '10000', 0),
(23619, 'Thames Reach Nursery ', 'thames-reach-nursery', 2701, 2813, NULL, '001', '<p>The project comprises a full fit out of the existing ground floor&nbsp;</p><p>shell area together with an external play area, to form a&nbsp;</p><p>Nursery catering for babies, toddlers, and pre-school children,&nbsp;</p><p>all as noted in the Tender Drawings.</p>', 4, 22, 1, '2022-11-21', '2023-03-13', 3, '2022-11-10 10:15:11', 'Nursery Premises ', 'The Reach, Battery Road,', 'London', 'SE28 0NY', 3, 3, 0, '0', 0),
(23620, '155 Drummond Street', '155-drummond-street', 17761, 20869, NULL, '01', '<p><span style=\"color: rgb(90, 109, 146);\">The building located at 155 Drummond Street will be partially demolished and built with two additional storeys on top of the existing height. To ensure the sustainability and to resonate with the existing historical architecture, the façade will be removed thru soft demolition and bricks will be recycled to be used as the new façade with prefabricated elements.</span></p>', 4, 24, 1, '2023-03-01', '2024-03-01', 1, '2022-11-11 09:55:27', 'Site Office', '155 Drummond Street', 'London', 'NW1 2PB', 3, 2, 0, '375', 0),
(23621, 'Station Point', 'station-point', 20738, 20856, NULL, 'Station Point', '<p>Mixed use development comprising of ground floor commercial retail units and residential uppers.</p>', 9, 22, 1, '2022-11-01', '2025-01-01', 1, '2022-11-11 14:05:18', 'Station Point', 'Station Approach', 'Purley', 'CR8 2AU', 2, 2, 0, '25000', 0),
(23622, 'Newman Road Sheffield ', 'newman-road-sheffield', 20764, 20887, NULL, '001', '<p>This new build construction comprises 6500ft commercial space on the ground floor and eight entry-level residential flats above.</p>', 13, 22, 1, '2022-12-12', '2023-12-11', 1, '2022-11-14 15:02:34', '320 Newman Road', '', 'Sheffield', 's9 1lx', 2, 2, 0, '11000', 0),
